import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _load_image_bytes(image_input: Any) -> bytes:
    if isinstance(image_input, (bytes, bytearray)):
        return bytes(image_input)
    if isinstance(image_input, str):
        if image_input.startswith("data:"):
            _, b64_data = image_input.split(",", 1)
            return base64.b64decode(b64_data)
        if os.path.exists(image_input):
            with open(image_input, "rb") as f:
                return f.read()
        return base64.b64decode(image_input)
    raise TypeError("image_input must be bytes, base64 string, data URI, or file path")


def _normalize_textract_blocks(blocks: List[Dict[str, Any]]) -> Dict[str, Any]:
    lines: List[Dict[str, Any]] = []
    words: List[Dict[str, Any]] = []
    full_text_parts: List[str] = []

    for block in blocks:
        block_type = block.get("BlockType")
        text = block.get("Text", "")
        if block_type == "LINE":
            lines.append(
                {
                    "text": text,
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )
            if text:
                full_text_parts.append(text)
        elif block_type == "WORD":
            words.append(
                {
                    "text": text,
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )

    return {
        "text": "\n".join(full_text_parts),
        "lines": lines,
        "words": words,
    }


def extract_text(image_input: Any, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract plain text and basic layout data from a scanned document image using Amazon Textract.

    Args:
        image_input: Path to image, raw bytes, base64 string, or data URI.
        region_name: Optional AWS region override.

    Returns:
        Dictionary with keys: text, lines, words, raw_response.
    """
    image_bytes = _load_image_bytes(image_input)

    textract = boto3.client("textract", region_name=region_name)
    response = textract.detect_document_text(Document={"Bytes": image_bytes})

    normalized = _normalize_textract_blocks(response.get("Blocks", []))
    normalized["raw_response"] = response
    return normalized
